var TRACK=50;
function createGame(n){ n=Math.max(2,Math.min(4,n||2)); var players=[];
  for(var i=0;i<n;i++) players.push({pos:0, finished:false});
  return {players:players, turn:0, track:TRACK, over:false, winner:-1}; }
function rollDie(rng){ rng=rng||Math.random; return 1+Math.floor(rng()*6); }
function allFinished(state){ return state.players.every(function(p){return p.finished;}); }
function step(state, steps){
  if(state.over) return {error:'游戏已结束'};
  var p=state.players[state.turn];
  if(p.finished) return {error:'当前玩家已完成'};
  var np=p.pos+steps;
  if(np>=state.track){ p.pos=state.track; p.finished=true; state.over=true; state.winner=state.turn; return {pos:p.pos, finished:true, win:true}; }
  p.pos=np;
  for(var i=0;i<state.players.length;i++){ if(i!==state.turn && state.players[i].pos===np && !state.players[i].finished){ state.players[i].pos=0; } }
  state.turn=(state.turn+1)%state.players.length;
  return {pos:p.pos, finished:false, win:false};
}
var EXPORTS={createGame:createGame, rollDie:rollDie, step:step, TRACK:TRACK};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.LudoForgePure = EXPORTS; }
